// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Order, Mode, genericndarray } from '@stdlib/types/ndarray';
import { Collection, AccessorArrayLike } from '@stdlib/types/array';

/**
* Interface describing function options.
*/
interface Options {
	/**
	* Array order (either 'row-major' (C-style) or 'column-major' (Fortran-style)).
	*/
	order?: Order;

	/**
	* Specifies how to handle a linear index which exceeds array dimensions (default: 'throw').
	*/
	mode?: Mode;

	/**
	* Boolean indicating whether an array should be read-only (default: false).
	*/
	readonly?: boolean;
}

/**
* Interface defining a typed vector constructor which is both "newable" and "callable".
*/
interface GenericVector {
	/**
	* Creates a "generic" vector (i.e., a one-dimensional ndarray).
	*
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only vector
	* @param options.mode - specifies how to handle indices which exceed vector dimensions
	* @param options.order - memory layout (either row-major or column-major)
	* @returns one-dimensional ndarray
	*
	* @example
	* var numel = require( '@stdlib/ndarray/numel' );
	*
	* var arr = new GenericVector();
	* // returns <ndarray>
	*
	* var len = numel( arr );
	* // returns 0
	*/
	new ( options?: Options ): genericndarray<unknown>;

	/**
	* Creates a "generic" vector (i.e., a one-dimensional ndarray).
	*
	* @param length - vector length
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only vector
	* @param options.mode - specifies how to handle indices which exceed vector dimensions
	* @param options.order - memory layout (either row-major or column-major)
	* @returns one-dimensional ndarray
	*
	* @example
	* var numel = require( '@stdlib/ndarray/numel' );
	*
	* var arr = new GenericVector( 2 );
	* // returns <ndarray>
	*
	* var len = numel( arr );
	* // returns 2
	*/
	new ( length: number, options?: Options ): genericndarray<unknown>;

	/**
	* Creates a "generic" vector (i.e., a one-dimensional ndarray).
	*
	* @param obj - array-like object or iterable from which to generate a vector
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only vector
	* @param options.mode - specifies how to handle indices which exceed vector dimensions
	* @param options.order - memory layout (either row-major or column-major)
	* @returns one-dimensional ndarray
	*
	* @example
	* var numel = require( '@stdlib/ndarray/numel' );
	*
	* var arr = new GenericVector( [ 1.0, 2.0 ] );
	* // returns <ndarray>
	*
	* var len = numel( arr );
	* // returns 2
	*/
	new <T = unknown>( obj: Collection<T> | AccessorArrayLike<T> | Iterable<T>, options?: Options ): genericndarray<T>;

	/**
	* Creates a "generic" vector (i.e., a one-dimensional ndarray).
	*
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only vector
	* @param options.mode - specifies how to handle indices which exceed vector dimensions
	* @param options.order - memory layout (either row-major or column-major)
	* @returns one-dimensional ndarray
	*
	* @example
	* var numel = require( '@stdlib/ndarray/numel' );
	*
	* var arr = new GenericVector();
	* // returns <ndarray>
	*
	* var len = numel( arr );
	* // returns 0
	*/
	( options?: Options ): genericndarray<unknown>;

	/**
	* Creates a "generic" vector (i.e., a one-dimensional ndarray).
	*
	* @param length - vector length
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only vector
	* @param options.mode - specifies how to handle indices which exceed vector dimensions
	* @param options.order - memory layout (either row-major or column-major)
	* @returns one-dimensional ndarray
	*
	* @example
	* var numel = require( '@stdlib/ndarray/numel' );
	*
	* var arr = new GenericVector( 2 );
	* // returns <ndarray>
	*
	* var len = numel( arr );
	* // returns 2
	*/
	( length: number, options?: Options ): genericndarray<unknown>;

	/**
	* Creates a "generic" vector (i.e., a one-dimensional ndarray).
	*
	* @param obj - array-like object or iterable from which to generate a vector
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only vector
	* @param options.mode - specifies how to handle indices which exceed vector dimensions
	* @param options.order - memory layout (either row-major or column-major)
	* @returns one-dimensional ndarray
	*
	* @example
	* var numel = require( '@stdlib/ndarray/numel' );
	*
	* var arr = new GenericVector( [ 1.0, 2.0 ] );
	* // returns <ndarray>
	*
	* var len = numel( arr );
	* // returns 2
	*/
	<T = unknown>( obj: Collection<T> | AccessorArrayLike<T> | Iterable<T>, options?: Options ): genericndarray<T>;
}

/**
* Creates a "generic" vector (i.e., a one-dimensional ndarray).
*
* @param arg - length, typed array, array-like object, or iterable
* @param options - function options
* @param options.readonly - boolean indicating whether to return a read-only vector
* @param options.mode - specifies how to handle indices which exceed vector dimensions
* @param options.order - memory layout (either row-major or column-major)
* @returns one-dimensional ndarray
*
* @example
* var numel = require( '@stdlib/ndarray/numel' );
*
* var arr = new GenericVector();
* // returns <ndarray>
*
* var len = numel( arr );
* // returns 0
*
* @example
* var numel = require( '@stdlib/ndarray/numel' );
*
* var arr = new GenericVector( 2 );
* // returns <ndarray>
*
* var len = numel( arr );
* // returns 2
*
* @example
* var numel = require( '@stdlib/ndarray/numel' );
*
* var arr = new GenericVector( [ 1.0, 2.0 ] );
* // returns <ndarray>
*
* var len = numel( arr );
* // returns 2
*/
declare var ctor: GenericVector;


// EXPORTS //

export = ctor;
